local BonsaiCultivator = {}
local PRODUCTS = {
    small_juniper_bonsai = { name = "Majhen brinov bonsaj", woodCost = 1, clayCost = 1, time = 4, cost = 50, beauty = 22, prestige = 2, happiness = 1, description = "Majhen brinov bonsaj v glineni posodi." },
    ornate_pine_bonsai = { name = "Izrezljan borov bonsaj", woodCost = 2, clayCost = 2, marbleCost = 1, time = 7, cost = 140, beauty = 38, prestige = 5, happiness = 2, description = "Borov bonsaj z marmornim podstavkom." },
    bronze_pot_bonsai = { name = "Bronastolonec bonsaj", woodCost = 2, clayCost = 2, bronzeCost = 2, marbleCost = 1, time = 10, cost = 310, beauty = 52, prestige = 10, happiness = 3, description = "Bonsaj v bronastem loncu za bogate dvorjane." },
    silver_tray_bonsai = { name = "Srebrnopolica bonsaj", woodCost = 2, clayCost = 2, silverCost = 2, marbleCost = 1, time = 13, cost = 740, beauty = 65, prestige = 17, happiness = 5, description = "Bonsaj na srebrni polici za visoke plemiče." },
    gold_trimmed_bonsai = { name = "Zlatookrasni bonsaj", woodCost = 3, clayCost = 2, goldCost = 2, silverCost = 1, marbleCost = 2, jewelCost = 1, time = 17, cost = 1650, beauty = 78, prestige = 27, happiness = 7, description = "Bonsaj z zlatimi okraski in dragulji za visoko plemstvo." },
    royal_grand_bonsai = { name = "Kraljevski veliki bonsaj", woodCost = 5, clayCost = 3, goldCost = 3, silverCost = 2, marbleCost = 4, jewelCost = 2, pearlCost = 2, time = 24, cost = 4100, beauty = 94, prestige = 60, happiness = 13, description = "Veliki kraljevski bonsaj z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    bonsai_garden = { name = "Bonsajski vrt", cost = { gold = 320, wood = 130, stone = 220, clay = 8 }, upkeep = 7, qualityBonus = 5 },
    cultivator_salon = { name = "Vzgojna dvorana", cost = { gold = 1100, wood = 290, stone = 460, marble = 6, clay = 14 }, upkeep = 27, qualityBonus = 18 },
    master_atelier = { name = "Mojstrski atelje", cost = { gold = 2600, wood = 370, stone = 690, silver = 36, bronze = 8 }, upkeep = 64, qualityBonus = 30 },
    royal_bonsai_palace = { name = "Kraljevska bonsajska palača", cost = { gold = 11500, wood = 600, stone = 1050, gold = 72, jewel = 20 }, upkeep = 225, qualityBonus = 55, prestigeBonus = 50 },
}
BonsaiCultivator.woodStock = 14; BonsaiCultivator.clayStock = 14; BonsaiCultivator.bronzeStock = 8; BonsaiCultivator.marbleStock = 10; BonsaiCultivator.silverStock = 8; BonsaiCultivator.goldStock = 6; BonsaiCultivator.jewelStock = 6; BonsaiCultivator.pearlStock = 4
BonsaiCultivator.productStock = {}; BonsaiCultivator.buildings = {}; BonsaiCultivator.maker = nil; BonsaiCultivator.activeMaking = {}; BonsaiCultivator.totalProducts = 0; BonsaiCultivator.dayTimer = 0
function BonsaiCultivator.init() BonsaiCultivator.woodStock=14; BonsaiCultivator.clayStock=14; BonsaiCultivator.bronzeStock=8; BonsaiCultivator.marbleStock=10; BonsaiCultivator.silverStock=8; BonsaiCultivator.goldStock=6; BonsaiCultivator.jewelStock=6; BonsaiCultivator.pearlStock=4; BonsaiCultivator.productStock={}; BonsaiCultivator.buildings={}; BonsaiCultivator.maker=nil; BonsaiCultivator.activeMaking={}; BonsaiCultivator.totalProducts=0; BonsaiCultivator.dayTimer=0; print("[BonsaiCultivator] Royal Bonsai Cultivator System initialized (6 products, 4 buildings)") end
function BonsaiCultivator.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BonsaiCultivator.maker={name=n or ("Bonsajist "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bonsajist najet: %s (spretnost: %d)",BonsaiCultivator.maker.name,s),"success") end; return true end
function BonsaiCultivator.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BonsaiCultivator.build(id) local ok,e=BonsaiCultivator.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BonsaiCultivator.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BonsaiCultivator.getQualityBonus() local b=0; for _,bd in ipairs(BonsaiCultivator.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BonsaiCultivator.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and BonsaiCultivator.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.clayCost and BonsaiCultivator.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.bronzeCost and BonsaiCultivator.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.marbleCost and BonsaiCultivator.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.silverCost and BonsaiCultivator.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BonsaiCultivator.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BonsaiCultivator.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BonsaiCultivator.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BonsaiCultivator.buildings==0 then return false,"Potreben bonsajski vrt" end; if not BonsaiCultivator.maker then return false,"Potreben bonsajist" end; return true end
function BonsaiCultivator.make(pt,qty) qty=qty or 1; local ok,e=BonsaiCultivator.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then BonsaiCultivator.woodStock=BonsaiCultivator.woodStock-d.woodCost*qty end; if d.clayCost then BonsaiCultivator.clayStock=BonsaiCultivator.clayStock-d.clayCost*qty end; if d.bronzeCost then BonsaiCultivator.bronzeStock=BonsaiCultivator.bronzeStock-d.bronzeCost*qty end; if d.marbleCost then BonsaiCultivator.marbleStock=BonsaiCultivator.marbleStock-d.marbleCost*qty end; if d.silverCost then BonsaiCultivator.silverStock=BonsaiCultivator.silverStock-d.silverCost*qty end; if d.goldCost then BonsaiCultivator.goldStock=BonsaiCultivator.goldStock-d.goldCost*qty end; if d.jewelCost then BonsaiCultivator.jewelStock=BonsaiCultivator.jewelStock-d.jewelCost*qty end; if d.pearlCost then BonsaiCultivator.pearlStock=BonsaiCultivator.pearlStock-d.pearlCost*qty end; local t=d.time; if BonsaiCultivator.maker then t=math.max(1,t-math.floor(BonsaiCultivator.maker.skill/12)) end; table.insert(BonsaiCultivator.activeMaking,{id="bonsai_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BonsaiCultivator.completeMaking(m) local q=1.0+(BonsaiCultivator.getQualityBonus()/100); if BonsaiCultivator.maker then q=q+(BonsaiCultivator.maker.skill/150) end; q=math.min(2.5,q); BonsaiCultivator.productStock[m.productType]=(BonsaiCultivator.productStock[m.productType] or 0)+m.quantity; BonsaiCultivator.totalProducts=BonsaiCultivator.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BonsaiCultivator.maker then BonsaiCultivator.maker.itemsMade=BonsaiCultivator.maker.itemsMade+m.quantity; if math.random()<0.25 then BonsaiCultivator.maker.skill=math.min(100,BonsaiCultivator.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bonsaj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bonsai.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function BonsaiCultivator.update(dt) if not _G.state then return end; BonsaiCultivator.dayTimer=BonsaiCultivator.dayTimer+dt; if BonsaiCultivator.dayTimer>=30 then BonsaiCultivator.dayTimer=0; for i=#BonsaiCultivator.activeMaking,1,-1 do local m=BonsaiCultivator.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BonsaiCultivator.completeMaking(m); table.remove(BonsaiCultivator.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BonsaiCultivator.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BonsaiCultivator.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BonsaiCultivator.getStats() return {woodStock=BonsaiCultivator.woodStock,clayStock=BonsaiCultivator.clayStock,bronzeStock=BonsaiCultivator.bronzeStock,marbleStock=BonsaiCultivator.marbleStock,silverStock=BonsaiCultivator.silverStock,goldStock=BonsaiCultivator.goldStock,jewelStock=BonsaiCultivator.jewelStock,pearlStock=BonsaiCultivator.pearlStock,productStock=BonsaiCultivator.productStock,numBuildings=#BonsaiCultivator.buildings,hasMaker=BonsaiCultivator.maker~=nil,makerName=BonsaiCultivator.maker and BonsaiCultivator.maker.name or "—",makerSkill=BonsaiCultivator.maker and BonsaiCultivator.maker.skill or 0,activeMaking=#BonsaiCultivator.activeMaking,totalProducts=BonsaiCultivator.totalProducts} end
return BonsaiCultivator
